"""Tracing and metrics configuration loaded from ``integrations.yml``.

Engine projects declare tracing under ``tracing:`` (one entry, or a list with
at most one Langfuse entry and at most one OTLP or Jaeger entry) and OTLP
metrics under ``metrics:``. Legacy projects keep those blocks in
``endpoints.yml``.
"""

from __future__ import annotations

from pathlib import Path
from typing import Any, Literal, Mapping, Optional, Sequence, Union, cast

import structlog
from pydantic import BaseModel, ConfigDict, Field, ValidationError, model_validator
from ruamel import yaml

from rasa.mantle.config.sections import read_integrations_section_node
from rasa.shared.exceptions import RasaException
from rasa.shared.project_structure import MANTLE_INTEGRATIONS_FILE
from rasa.shared.utils.yaml import construct_yaml_node
from rasa.tracing.constants import ENDPOINTS_OTLP_BACKEND_TYPE, TRACING_TYPE_LANGFUSE

structlogger = structlog.get_logger()

TRACING_KEY = "tracing"
METRICS_KEY = "metrics"
TYPE_KEY = "type"
TRACING_TYPE_JAEGER = "jaeger"
TRACING_TYPE_OTLP = ENDPOINTS_OTLP_BACKEND_TYPE

# Which configurer consumes a ``tracing:`` entry: Langfuse, or the OTLP/Jaeger
# backend tracer.
TracerKind = Literal["langfuse", "backend"]

_SUPPORTED_TRACING_TYPES = (
    TRACING_TYPE_LANGFUSE,
    TRACING_TYPE_OTLP,
    TRACING_TYPE_JAEGER,
)


class LangfuseTracingSettings(BaseModel):
    """The ``tracing:`` section of ``integrations.yml`` for Langfuse.

    Mirrors the Langfuse block historically authored under ``endpoints.yml``.
    Required keys match :mod:`rasa.tracing.langfuse_config`; optional Langfuse
    knobs (``timeout``, ``debug``, ``environment``, …) are passed through via
    ``extra="allow"`` so the apply path can set the corresponding env vars.
    """

    model_config = ConfigDict(frozen=True, extra="allow")

    type: str = Field(min_length=1)
    public_key: str = Field(min_length=1)
    private_key: str = Field(min_length=1)
    host: str = Field(min_length=1)

    def as_config_dict(self) -> dict[str, Any]:
        """Return a plain dict suitable for Langfuse apply helpers."""
        return self.model_dump()


class OtlpCollectorSettings(BaseModel):
    """OTLP collector settings for ``tracing:`` or ``metrics:``.

    Field names match the endpoints block the OTLP configurers already read
    (``endpoint``, ``insecure``, ``root_certificates``, ``service_name``).
    """

    model_config = ConfigDict(frozen=True, extra="forbid", hide_input_in_errors=True)

    type: Literal["otlp"]
    endpoint: str = Field(min_length=1)
    insecure: bool | None = None
    root_certificates: str | None = Field(default=None, min_length=1)
    service_name: str | None = Field(default=None, min_length=1)

    def as_config_dict(self) -> dict[str, Any]:
        """Return a plain dict suitable for an OTLP ``EndpointConfig``."""
        return self.model_dump(exclude_none=True)


class JaegerTracingSettings(BaseModel):
    """Jaeger settings for the ``tracing:`` section of ``integrations.yml``.

    ``host`` and ``port`` are optional. The Jaeger configurer applies its own
    defaults when they are omitted (``localhost`` and ``4317``). Credentials
    require an explicit ``insecure`` choice so they are never sent in
    plaintext by default.
    """

    model_config = ConfigDict(frozen=True, extra="forbid", hide_input_in_errors=True)

    type: Literal["jaeger"]
    host: str | None = Field(default=None, min_length=1)
    port: int | None = Field(default=None, gt=0, le=65535)
    username: str | None = Field(default=None, min_length=1)
    password: str | None = Field(default=None, min_length=1)
    insecure: bool | None = None
    root_certificates: str | None = Field(default=None, min_length=1)
    service_name: str | None = Field(default=None, min_length=1)
    sync_export: bool | None = None

    @model_validator(mode="after")
    def _require_explicit_insecure_with_credentials(self) -> JaegerTracingSettings:
        if (self.username or self.password) and self.insecure is None:
            raise ValueError(
                "Jaeger 'username'/'password' require an explicit 'insecure' "
                "setting. Set 'insecure: false' (optionally with "
                "'root_certificates') to send them over TLS, or "
                "'insecure: true' to send them unencrypted."
            )
        return self

    def as_config_dict(self) -> dict[str, Any]:
        """Return a plain dict suitable for a Jaeger ``EndpointConfig``."""
        return self.model_dump(exclude_none=True)


BackendTracingSettings = Union[OtlpCollectorSettings, JaegerTracingSettings]
TracingEntrySettings = Union[LangfuseTracingSettings, BackendTracingSettings]


class TracingSettings(BaseModel):
    """All tracers declared under ``tracing:`` in ``integrations.yml``.

    Langfuse and a backend tracer (OTLP or Jaeger) are independent, so a
    project may declare one of each, the same rule ``endpoints.yml`` applies.
    """

    model_config = ConfigDict(frozen=True)

    langfuse: Optional[LangfuseTracingSettings] = None
    backend: Optional[BackendTracingSettings] = None


def parse_tracing(
    raw_tracing: Union[Mapping[str, Any], Sequence[Any]],
) -> TracingSettings:
    """Validate a raw ``tracing:`` section from ``integrations.yml``.

    Args:
        raw_tracing: The ``tracing:`` value as read from integrations.yml:
            a single tracer mapping, or a list of tracer mappings.

    Returns:
        The validated Langfuse and backend tracers, either of which may be
        unset.

    Raises:
        RasaException: If an entry is not a mapping, has an unsupported
            ``type``, fails schema validation, or the list declares more than
            one Langfuse or more than one backend tracer.
    """
    entries = [raw_tracing] if isinstance(raw_tracing, Mapping) else raw_tracing
    langfuse: Optional[LangfuseTracingSettings] = None
    backend: Optional[BackendTracingSettings] = None
    for entry in entries:
        if not isinstance(entry, Mapping):
            raise RasaException(
                f"Each '{TRACING_KEY}' entry in '{MANTLE_INTEGRATIONS_FILE}' must "
                f"be a mapping, but got '{type(entry).__name__}'."
            )
        settings = _parse_tracing_entry(entry)
        if isinstance(settings, LangfuseTracingSettings):
            if langfuse is not None:
                raise RasaException(
                    f"'{TRACING_KEY}' in '{MANTLE_INTEGRATIONS_FILE}' declares more "
                    f"than one '{TRACING_TYPE_LANGFUSE}' entry. Only one is "
                    "allowed."
                )
            langfuse = settings
        else:
            if backend is not None:
                raise RasaException(
                    f"'{TRACING_KEY}' in '{MANTLE_INTEGRATIONS_FILE}' declares more "
                    f"than one '{TRACING_TYPE_OTLP}' or '{TRACING_TYPE_JAEGER}' "
                    "entry. Only one backend tracer is allowed."
                )
            backend = settings
    return TracingSettings(langfuse=langfuse, backend=backend)


def _parse_tracing_entry(raw_entry: Mapping[str, Any]) -> TracingEntrySettings:
    """Validate one tracer mapping by its ``type``."""
    tracing_type = raw_entry.get(TYPE_KEY)
    if tracing_type == TRACING_TYPE_LANGFUSE:
        model: type[BaseModel] = LangfuseTracingSettings
    elif tracing_type == TRACING_TYPE_OTLP:
        model = OtlpCollectorSettings
    elif tracing_type == TRACING_TYPE_JAEGER:
        model = JaegerTracingSettings
    else:
        supported = ", ".join(f"'{name}'" for name in _SUPPORTED_TRACING_TYPES)
        raise RasaException(
            f"'{TRACING_KEY}' in '{MANTLE_INTEGRATIONS_FILE}' supports types "
            f"{supported}, got '{tracing_type}'."
        )

    try:
        settings = model.model_validate(dict(raw_entry))
    except ValidationError as error:
        raise RasaException(
            f"Invalid '{TRACING_KEY}' configuration in '{MANTLE_INTEGRATIONS_FILE}': "
            f"{error}"
        ) from error
    return cast(TracingEntrySettings, settings)


def parse_metrics(raw_metrics: Mapping[str, Any]) -> OtlpCollectorSettings:
    """Validate a raw ``metrics:`` mapping from ``integrations.yml``.

    Args:
        raw_metrics: The ``metrics:`` mapping as read from integrations.yml.

    Returns:
        Validated OTLP collector settings.

    Raises:
        RasaException: If ``type`` is not ``otlp`` or the mapping fails schema
            validation.
    """
    metrics_type = raw_metrics.get(TYPE_KEY)
    if metrics_type != TRACING_TYPE_OTLP:
        raise RasaException(
            f"'{METRICS_KEY}' in '{MANTLE_INTEGRATIONS_FILE}' only supports "
            f"type '{TRACING_TYPE_OTLP}', got '{metrics_type}'."
        )

    try:
        return OtlpCollectorSettings.model_validate(dict(raw_metrics))
    except ValidationError as error:
        raise RasaException(
            f"Invalid '{METRICS_KEY}' configuration in '{MANTLE_INTEGRATIONS_FILE}': "
            f"{error}"
        ) from error


def load_integration_tracing(
    project_root: str | Path,
    *,
    tracer: Optional[TracerKind] = None,
) -> Optional[TracingSettings]:
    """Load tracing configuration from a project's ``integrations.yml``.

    Environment variables are expanded at read time for OTLP and Jaeger.
    Langfuse ``public_key`` / ``private_key`` stay as ``${VAR}`` literals at
    parse time (deferred resolution) so the apply path can validate syntax and
    resolve them when Langfuse configures at startup.

    Expansion is scoped to each ``tracing:`` entry, so an unset variable
    elsewhere in the file (another section, or another tracer's entry when
    ``tracer`` is given) does not stop this tracer from loading.

    Args:
        project_root: Directory expected to contain ``integrations.yml``.
        tracer: The tracer the caller will configure. An entry of another
            kind whose environment variables cannot be expanded is left out
            instead of raising; its own caller reports it. ``None`` requires
            every entry to expand.

    Returns:
        Validated tracing settings, or ``None`` if the file does not exist or
        does not declare a ``tracing:`` block.

    Raises:
        RasaException: If ``tracing:`` is present but is neither a mapping nor
            a list, references an unset environment variable in an entry the
            caller needs, or fails validation (including unsupported tracer
            types and duplicate tracers).
    """
    section = read_integrations_section_node(project_root, TRACING_KEY, allow_list=True)
    if section is None:
        return None

    integration_file = Path(project_root) / MANTLE_INTEGRATIONS_FILE
    entry_nodes = section.value if isinstance(section, yaml.SequenceNode) else [section]
    entries = []
    for entry_node in entry_nodes:
        try:
            entries.append(construct_yaml_node(entry_node, filename=integration_file))
        except RasaException:
            if tracer is None or _tracer_kind(entry_node) in (tracer, None):
                raise

    settings = parse_tracing(entries)
    structlogger.debug(
        "mantle.tracing.loaded_from_integration",
        langfuse=settings.langfuse is not None,
        backend_type=settings.backend.type if settings.backend else None,
    )
    return settings


def load_integration_metrics(
    project_root: str | Path,
) -> Optional[OtlpCollectorSettings]:
    """Load metrics configuration from a project's ``integrations.yml``.

    Environment variables are expanded in the ``metrics:`` block only, so an
    unset variable in another section does not stop metrics from loading.

    Args:
        project_root: Directory expected to contain ``integrations.yml``.

    Returns:
        Validated OTLP metrics settings, or ``None`` if the file does not exist
        or does not declare a ``metrics:`` block.

    Raises:
        RasaException: If ``metrics:`` is present but not a mapping, references
            an unset environment variable, or fails validation.
    """
    section = read_integrations_section_node(project_root, METRICS_KEY)
    if section is None:
        return None

    raw_metrics = construct_yaml_node(
        section, filename=Path(project_root) / MANTLE_INTEGRATIONS_FILE
    )
    settings = parse_metrics(raw_metrics)
    structlogger.debug(
        "mantle.metrics.loaded_from_integration",
        metrics_type=settings.type,
    )
    return settings


def _tracer_kind(entry_node: yaml.Node) -> Optional[TracerKind]:
    """Return which tracer an unexpanded ``tracing:`` entry configures, if known."""
    raw_entry = construct_yaml_node(entry_node, expand_env_vars=False)
    if not isinstance(raw_entry, Mapping):
        return None
    tracing_type = raw_entry.get(TYPE_KEY)
    if tracing_type == TRACING_TYPE_LANGFUSE:
        return "langfuse"
    if tracing_type in (TRACING_TYPE_OTLP, TRACING_TYPE_JAEGER):
        return "backend"
    return None
